ALTER POLICY "own_memberships" ON "memberships" TO pos_app USING (nullif(current_setting('app.tenant_id', true), '')::uuid IS NULL AND "memberships"."user_id" = nullif(current_setting('app.user_id', true), '')::uuid);--> statement-breakpoint
ALTER POLICY "tenant_access" ON "tenants" TO pos_app USING ("tenants"."id" = nullif(current_setting('app.tenant_id', true), '')::uuid OR (nullif(current_setting('app.tenant_id', true), '')::uuid IS NULL AND "tenants"."id" IN (SELECT m.tenant_id FROM memberships m WHERE m.user_id = nullif(current_setting('app.user_id', true), '')::uuid)));